import type { SlotGridLayout } from '../models/SlotGrid';

export interface SlotLayoutSource {
    readonly cols: number;
    readonly rows: number;
}

// 盤面最上面不計分的隱藏列格數
export interface SlotBoardDamp {
    readonly top: number;
    readonly bottom: number;
}

export const TEMPORARY_SLOT_LAYOUT_SOURCE: SlotLayoutSource = { cols: 6, rows: 5 };

// 照 games/eyeofhorus.json 的 board.damp_top damp_bottom
const BOARD_DAMP_BY_GAME: Readonly<Record<string, SlotBoardDamp>> = {
    '1001': { top: 1, bottom: 0 },
};

/**
 * 取得該遊戲盤面上下的隱藏列格數。後端 `rl` 每軸是「上隱藏列＋可見格＋下隱藏列」，解碼時要先扣掉。
 *
 * @param gameId 遊戲代號。
 * @returns 上下的隱藏列格數；未登記的遊戲兩邊都是 0。
 */
export function getBoardDamp(gameId: string): SlotBoardDamp {
    return BOARD_DAMP_BY_GAME[gameId] ?? { top: 0, bottom: 0 };
}

export function createSlotGridLayout(source: SlotLayoutSource): SlotGridLayout {
    return {
        columns: source.cols,
        visibleRows: source.rows,
        bufferRows: 0,
        bufferPlacement: 'start',
        sourceRowOrder: 'top-down',
        presentationRowOrder: 'top-down',
    };
}
