import type { SlotApiBetRequest, SlotApiEntry, SlotApiEnvelope, SlotApiHistoryList, SlotApiHistoryRoundDetail, SlotApiJackpotsResponse, SlotApiStep } from './SlotApiTypes';
import { SLOT_API_CODE, SlotApiHttpError } from './SlotApiTypes';
import { RestClient, RestClientError } from './RestClient';

/** bet 每秒最多 10 次（附錄 B），兩次請求至少間隔這麼久 */
const BET_MIN_INTERVAL_MS = 100;

/**
 * SlotApiClient
 *
 * 玩家端 API v8.1（slot-integration.md §5）的 HTTP 呼叫：entry、bet、jackpots、history。每個請求都帶
 * `Authorization: Bearer <t>`；回應解開信封後原樣交給呼叫端，轉成前端模型在 SlotRoundMapper。
 * WebSocket 只有推播（§6），這款還沒接。
 */
export class SlotApiClient {
    private readonly restClient: RestClient;
    private token = '';
    private lastBetAt = 0;

    /**
     * @param httpBaseUrl 玩家端 API 的基底網址（假資料模式是假後端的網址）。
     */
    constructor(httpBaseUrl: string) {
        this.restClient = new RestClient({
            baseUrl: httpBaseUrl,
            // 5xx／逾時重試 2 次、4xx 不重試；bet 依附錄 B 自己重送，不走這個（見 bet）
            timeoutMs: 15000,
            retries: 2,
            retryDelayMs: 300,
            getAuthHeaders: () => (this.token ? { Authorization: `Bearer ${this.token}` } : {}),
        });
    }

    /**
     * 設定之後每個請求要帶的 token。
     *
     * @param token 網址上的 `t`。
     */
    public setToken(token: string): void {
        this.token = token;
    }

    /**
     * 進場（§5.1）：每次載入遊戲都打，回限紅、最近一步 `ls` 等。永遠回信封，`4022`／`4016` 也是 HTTP 200。
     *
     * @param gameId 遊戲代號（`gid`）。
     * @returns entry 的 `data`。
     * @throws SlotApiHttpError
     */
    public async entry(gameId: string): Promise<SlotApiEntry> {
        return this.postPlayer<SlotApiEntry>('/player/entry', { gid: gameId });
    }

    /**
     * 獎池水位（§5.7）：不依幣別過濾，呼叫端要自己比對 currency；每分鐘最多 30 次。
     *
     * @param gameId 遊戲代號。
     * @returns 各層獎池。
     * @throws SlotApiHttpError
     */
    public async jackpots(gameId: string): Promise<SlotApiJackpotsResponse> {
        return this.getPlayer<SlotApiJackpotsResponse>('/player/jackpots', { game_id: gameId });
    }

    /**
     * 注單列表（§5.4），只列已結算的局。
     *
     * @param gameId 遊戲代號。
     * @param page 頁碼，1 起。
     * @param pageSize 每頁幾筆。
     * @returns 列表模式的 `data`。
     * @throws SlotApiHttpError
     */
    public async historyList(gameId: string, page: number, pageSize: number): Promise<SlotApiHistoryList> {
        return this.getPlayer<SlotApiHistoryList>('/player/history', { game_id: gameId, page, page_size: pageSize });
    }

    /**
     * 單局重播（§5.4）：母單與全部細單。
     *
     * @param roundId 局號。
     * @returns 單局模式的 `data`。
     * @throws SlotApiHttpError
     */
    public async historyRound(roundId: string): Promise<SlotApiHistoryRoundDetail> {
        return this.getPlayer<SlotApiHistoryRoundDetail>('/player/history', { round_id: roundId });
    }

    /**
     * 下注（§5.2）：開新局與續打（連消、免費遊戲）同一支，由 `id` 決定做什麼。
     * 暫時性失敗依附錄 B 用**同一個** `id` 重送，其他錯誤直接丟出。
     *
     * @param request 下注請求。
     * @returns 這一步的步驟物件。
     * @throws SlotApiHttpError
     */
    public async bet(request: SlotApiBetRequest): Promise<SlotApiStep> {
        for (let attempt = 0; ; attempt++) {
            await this.waitBetInterval();
            try {
                return await this.postPlayer<SlotApiStep>('/player/bet', request, 0);
            } catch (error) {
                const delayMs = error instanceof SlotApiHttpError ? this.betRetryDelayMs(error, attempt) : null;
                if (delayMs === null) throw error;
                await new Promise<void>((resolve) => setTimeout(resolve, delayMs));
            }
        }
    }

    /**
     * bet 失敗後要等多久再重送。
     *
     * 文件有寫的照文件：4017／4022 間隔 1、2、4 秒（三次）、4029／4030 等 Retry-After、4015 立刻重送。
     * 文件沒寫次數與間隔的（網路逾時、4500），沿用 HTTP 重試的 2 次、間隔 300ms 線性遞增。
     *
     * @param error 這次的錯誤。
     * @param attempt 已經失敗幾次（0 起）。
     * @returns 毫秒數；null 代表不重送。
     */
    private betRetryDelayMs(error: SlotApiHttpError, attempt: number): number | null {
        const pending = error.code === SLOT_API_CODE.STEP_WRITING || error.code === SLOT_API_CODE.PROCESSING;
        if (attempt >= (pending ? 3 : 2)) return null;
        if (pending) return 1000 * 2 ** attempt;
        if (error.code === SLOT_API_CODE.BET_VOID) return 0;
        if (error.code === SLOT_API_CODE.RATE_LIMITED || error.code === SLOT_API_CODE.BUSY) return (error.retryAfterSec ?? 1) * 1000;
        if (error.kind === 'network' || error.code === SLOT_API_CODE.INTERNAL) return 300 * (attempt + 1);
        return null;
    }

    /**
     * 連續打 bet（連消、免費遊戲）時控制在每秒 10 次以內。
     *
     * @returns 距離上一次 bet 滿 {@link BET_MIN_INTERVAL_MS} 之後 resolve。
     */
    private async waitBetInterval(): Promise<void> {
        const wait = this.lastBetAt + BET_MIN_INTERVAL_MS - Date.now();
        this.lastBetAt = Date.now() + Math.max(0, wait);
        if (wait > 0) await new Promise<void>((resolve) => setTimeout(resolve, wait));
    }

    /**
     * 送玩家端 POST。
     *
     * @param path 路徑。
     * @param body 請求內容。
     * @param retries 5xx／逾時的重試次數；沒給用 RestClient 預設（2 次），bet 傳 0。
     * @returns 信封的 `data`。
     * @throws SlotApiHttpError
     */
    private async postPlayer<T>(path: string, body: unknown, retries?: number): Promise<T> {
        return this.unwrapPlayer(() => this.restClient.post<SlotApiEnvelope<T>>(path, body, { retries }));
    }

    /**
     * 送玩家端 GET，錯誤處理同 {@link postPlayer}。
     *
     * @param path 路徑。
     * @param query 查詢參數（snake_case）。
     * @returns 信封的 `data`。
     * @throws SlotApiHttpError
     */
    private async getPlayer<T>(path: string, query: Record<string, string | number>): Promise<T> {
        return this.unwrapPlayer(() => this.restClient.get<SlotApiEnvelope<T>>(path, { query }));
    }

    /**
     * 解開玩家端信封：HTTP 成功但 `code` 不是 0 的業務錯誤，以及 401／429／5xx，都轉成 SlotApiHttpError。
     *
     * @param send 送出請求的函式。
     * @returns 信封的 `data`。
     * @throws SlotApiHttpError；回應不是合法信封（沒有數字 `code`）時丟 Error。
     */
    private async unwrapPlayer<T>(send: () => Promise<SlotApiEnvelope<T>>): Promise<T> {
        let envelope: SlotApiEnvelope<T>;
        try {
            envelope = await send();
        } catch (error) {
            if (!(error instanceof RestClientError)) throw error;
            const failed = error.body as SlotApiEnvelope<unknown> | undefined;
            // 401 沒有 code：session 失效，上層要再打一次 entry
            const kind = error.status === 401 ? 'unauthorized' : error.status === undefined ? 'network' : failed?.code ? 'business' : 'http';
            throw new SlotApiHttpError(kind, failed?.code ?? 0, failed?.message ?? error.message, error.status ?? 0, failed?.support_ref, failed?.latest_step_id, error.retryAfterSec);
        }
        if (!envelope || typeof envelope.code !== 'number') {
            throw new Error('玩家端 API 回應格式不符：缺少數字 code');
        }
        if (envelope.code !== SLOT_API_CODE.OK) {
            throw new SlotApiHttpError('business', envelope.code, envelope.message ?? 'empty response', 200, envelope.support_ref, envelope.latest_step_id, envelope.retry_after);
        }
        return envelope.data as T;
    }
}
